// Hook del carrito: lo guarda en localStorage para conservarlo al recargar
// y evita mezclar productos de restaurantes diferentes en un mismo pedido.
function useCart() {
  const [cart, setCart] = useState<CartLine[]>(() => {
    try { return JSON.parse(localStorage.getItem('pq-cart') || '[]'); } catch { return []; }
  });
  useEffect(() => { localStorage.setItem('pq-cart', JSON.stringify(cart)); }, [cart]);
  const add = (product: Product, restaurantName: string) => setCart((current) => {
    const found = current.find((line) => line.id === product.id);
    if (current.length && current[0].restaurantId !== product.restaurantId) return [{ ...product, quantity: 1, restaurantName }];
    return found ? current.map((line) => line.id === product.id ? { ...line, quantity: line.quantity + 1 } : line) : [...current, { ...product, quantity: 1, restaurantName }];
  });
  const update = (id: number, amount: number) => setCart((current) => current.map((line) => line.id === id ? { ...line, quantity: Math.max(0, amount) } : line).filter((line) => line.quantity > 0));
  return { cart, add, update, clear: () => setCart([]) };
}

